import{_ as i,C as t,o,c as s,E as a,a2 as c}from"./chunks/framework.Bx6eOp9J.js";const g=JSON.parse('{"title":"Permitted Substitution Is Not Successful Repair","description":"","frontmatter":{"title":"Permitted Substitution Is Not Successful Repair","date":"2026-10-20","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"修复建议送达宿主前，最后一道替换检查实际保证什么，又留下哪些验证责任？","research_question_en":"What does the final response-substitution guard guarantee before host delivery?","summary":"Ten controlled calls distinguish protected original objects and arrays, accepted scalars and structured replacement content; these local compatibility outcomes do not establish repair efficacy or comprehensive safety.","sources":"ARIA pinned source and v1 appendix; Octagon pinned source; internal mechanism experiment","pageClass":"runtime-v6-article","item_id":"SIG-20261020-004","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-20-sig-20261020-004-final-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-10-20-sig-20261020-004.md","filePath":"en/engineering/2026-10-20-sig-20261020-004.md","lastUpdated":1792511535000}'),d={name:"en/engineering/2026-10-20-sig-20261020-004.md"};function l(p,e,u,h,b,m){const r=t("ArticleCover"),n=t("ArticleTableScroll");return o(),s("div",null,[a(r,{image:"/assets/covers/daily-2026-10-20-sig-20261020-004-final-cover.png",kicker:"Research",title:"Permitted Substitution Is Not Successful Repair",summary:"Ten controlled calls distinguish protected original objects and arrays, accepted scalars and structured replacement content; these local compatibility outcomes do not establish repair efficacy or comprehensive safety.",version:"2026-10-20",languageHref:"/zh/engineering/2026-10-20-sig-20261020-004",languageLabel:"中文"}),a(n,{language:"en"}),e[0]||(e[0]=c('<h1 id="permitted-substitution-is-not-successful-repair" tabindex="-1">Permitted Substitution Is Not Successful Repair <a class="header-anchor" href="#permitted-substitution-is-not-successful-repair" aria-label="Permalink to &quot;Permitted Substitution Is Not Successful Repair&quot;">​</a></h1><p>An original object caused a repair proposal to degrade to a shadow record, while an original number could retain a substitution decision. This contrast came from actual calls to a response-delivery guard. For adapter maintainers, it creates a concrete question: what does compatibility examine before anyone infers successful repair? Ten controlled inputs locate the boundary and identify the records still needed for enactment and benefit evaluation.</p><h2 id="locate-the-guard-before-interpreting-its-result" tabindex="-1">Locate the guard before interpreting its result <a class="header-anchor" href="#locate-the-guard-before-interpreting-its-result" aria-label="Permalink to &quot;Locate the guard before interpreting its result&quot;">​</a></h2><p>ARIA studies runtime repair with separate controller, host-delivery and evaluation responsibilities. We examined its final pending-response function, <code>validate_pending_substitution</code>. It retains substitution or degrades to shadow recording without replacement. That decision is not itself a receipt of host enactment. <a href="https://github.com/LabRAI/ARIA/blob/ce68c040cca0796b37fa8ae46e2a87a073f64001/src/aria/hook/controller.py" target="_blank" rel="noreferrer">Source: pinned controller</a></p><p>Other inspected source paths include capability checks, so this function must not be treated as the system&#39;s entire defense. We selected it because permission to deliver and effective recovery can disappear into one success label. The appendix describes continuation from reconstructed context; repair-record code separately checks patched-only success and verified materialization. None of that execution occurred in our ten calls. <a href="https://arxiv.org/html/2610.20780v1#A2" target="_blank" rel="noreferrer">Sources: Appendix B.3</a>, <a href="https://github.com/LabRAI/ARIA/blob/ce68c040cca0796b37fa8ae46e2a87a073f64001/src/repair/v5_records.py" target="_blank" rel="noreferrer">repair-record admission</a></p><h2 id="the-actual-boundary-in-ten-calls" tabindex="-1">The actual boundary in ten calls <a class="header-anchor" href="#the-actual-boundary-in-ten-calls" aria-label="Permalink to &quot;The actual boundary in ten calls&quot;">​</a></h2><p>Analysis ran the pinned original function body with actual upstream record types on October 20, 2026 using Windows 11 and Python 3.13.13. Abstract-syntax-tree extraction isolated dependencies while retaining the tested logic. It omitted import-time behavior and host integration. Inputs were explicitly controlled operations, not model outputs or recovered tasks. Production verified hash-bound records and added no experiment.</p><p>The complete ten-call set is below. Retained substitution corresponds to <code>substitute</code>; degraded shadow corresponds to <code>shadow</code>, which records without replacing.</p><table tabindex="0"><thead><tr><th>Controlled condition</th><th>Observed decision</th></tr></thead><tbody><tr><td>Plain-text replacement</td><td>Retain substitution</td></tr><tr><td>Original response has a protected flag</td><td>Degrade to shadow</td></tr><tr><td>Original response is an object</td><td>Degrade to shadow</td></tr><tr><td>Original response is an array</td><td>Degrade to shadow</td></tr><tr><td>Message role differs</td><td>Degrade to shadow</td></tr><tr><td>Replacement is empty</td><td>Degrade to shadow</td></tr><tr><td>Replacement is unchanged</td><td>Degrade to shadow</td></tr><tr><td>Original is a JSON string scalar</td><td>Retain substitution</td></tr><tr><td>Original is a JSON number scalar</td><td>Retain substitution</td></tr><tr><td>Original is plain text; replacement is itself an object</td><td>Retain substitution</td></tr></tbody></table><p>Source: ten internal per-call records, all matching expected outcomes. Raw records remain unpublished and access-restricted. These are neither task-success nor attack-success rates. The code reads host protection metadata and treats original content parsed as an object or array as protected. String and number scalars do not enter that object/array branch. It does not impose the same structural prohibition on replacement content for an original plain-text response. <a href="https://github.com/LabRAI/ARIA/blob/ce68c040cca0796b37fa8ae46e2a87a073f64001/src/aria/hook/controller.py" target="_blank" rel="noreferrer">Source: the same pinned pending-substitution function</a></p><h2 id="accepting-a-scalar-is-not-yet-a-vulnerability-finding" tabindex="-1">Accepting a scalar is not yet a vulnerability finding <a class="header-anchor" href="#accepting-a-scalar-is-not-yet-a-vulnerability-finding" aria-label="Permalink to &quot;Accepting a scalar is not yet a vulnerability finding&quot;">​</a></h2><p>Objects, arrays, strings and numbers can all be represented in JSON. Parseability is therefore not the full predicate used by this protection rule. Calling it protection for all structured responses would erase the observed distinction. The precise description is object/array recognition for the original response, alongside host-supplied protection metadata.</p><p>Accepting a scalar need not be a defect. A host could use protection metadata to mark machine-readable replies as nonreplaceable. Replacing plain text with an object could also satisfy a particular host contract. We did not inspect the complete native-adapter metadata path or test downstream schema enforcement. The asymmetry locates a contract responsibility; it does not establish a reachable production vulnerability or comprehensive defense failure.</p><p>A same-day experiment offers a limited comparison. Octagon&#39;s credit function checks current object identity and round while delegating remote observation to its caller. Both examined boundaries enforce a local precondition and rely on another layer for the meaning of an effect. Their threat models, objects and acceptance endpoints differ; this is neither security equivalence nor a ranking. <a href="https://github.com/cyber-arena-ai/octagon/blob/3bb9eb1bef72a454ee455ad3cc321933133cd3eb/flag/store.py" target="_blank" rel="noreferrer">Source: pinned credit implementation</a></p><h2 id="keep-proposal-enactment-and-benefit-records-separate" tabindex="-1">Keep proposal, enactment and benefit records separate <a class="header-anchor" href="#keep-proposal-enactment-and-benefit-records-separate" aria-label="Permalink to &quot;Keep proposal, enactment and benefit records separate&quot;">​</a></h2><p>Maintainers can inspect existing records by responsibility before interpreting one admission decision as a total outcome. The following is our proposed inspection framework, not a claim that new capabilities have been implemented.</p><table tabindex="0"><thead><tr><th>Stage and responsible party</th><th>Input and output to inspect</th><th>Condition preventing further inference</th></tr></thead><tbody><tr><td>Repair proposer</td><td>Original, replacement and rationale</td><td>No specified content change</td></tr><tr><td>Compatibility layer</td><td>Protection, role and content; substitute/shadow decision</td><td>Protected, incompatible, empty or unchanged content</td></tr><tr><td>Host enactment</td><td>Admitted content and host schema; actual adoption result</td><td>Not adopted, adoption failed or contract unclear</td></tr><tr><td>Evaluation</td><td>Actual result and control; recovery and harm records</td><td>Missing control, materialization or planned-pool coverage</td></tr></tbody></table><p>Only the second layer&#39;s ten inputs were executed locally. Repair-record and reporting duties were source observations; host adoption and evaluation were not run. The inspected report code distinguishes malformed output, explicit constraint violations and enacted score regression, with qualifications for incomplete pools. We measured no recovery rate, harm rate or latency. <a href="https://github.com/LabRAI/ARIA/blob/ce68c040cca0796b37fa8ae46e2a87a073f64001/scripts/aria/report_rq1_eval.py" target="_blank" rel="noreferrer">Source: evaluation reporting implementation</a></p><h2 id="evidence-and-sources" tabindex="-1">Evidence and sources <a class="header-anchor" href="#evidence-and-sources" aria-label="Permalink to &quot;Evidence and sources&quot;">​</a></h2><p>The ten calls are internal experimental evidence, not independent validation. Function branches and neighboring responsibilities are our source observations; separating responsibilities is our interpretation. Materials come from two distinct projects, but no independent third party reproduced these ten results. Publication, citation and code release do not close that gap.</p><p>The version scope is ARIA v1 and author-repository commit <code>ce68c040cca0796b37fa8ae46e2a87a073f64001</code>, plus Octagon commit <code>3bb9eb1bef72a454ee455ad3cc321933133cd3eb</code> for qualitative comparison. Sources were read and experiments completed on October 20, 2026. Internal scripts and results remain in an access-restricted local research archive. Source links provide inspection entry points, but this article does not claim to contain a complete public rerun package.</p><h2 id="the-next-verification-must-cross-the-host" tabindex="-1">The next verification must cross the host <a class="header-anchor" href="#the-next-verification-must-cross-the-host" aria-label="Permalink to &quot;The next verification must cross the host&quot;">​</a></h2><p>We did not run the whole controller, native adapters, model inference, training, paired continuations or benchmark tasks. A free-form text host might face no material risk from this object/scalar distinction; a strict-schema host needs to examine its actual integration contract.</p><p>Two concrete questions remain: which host metadata protects machine-readable scalars, and where is admitted replacement content schema-checked and actually enacted? Binding proposal, compatibility decision, host enactment and final evaluation would create grounds for discussing repair benefit. Current evidence supports an accurate description of this one local boundary.</p>',24))])}const y=i(d,[["render",l]]);export{g as __pageData,y as default};
